from pathlib import Path
import os,json,math
ROOT=Path(__file__).resolve().parent/'vectorizacion_A/sensibilidad_angulo'
os.environ.setdefault('MPLCONFIGDIR',str(ROOT/'mpl-cache'))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
s=json.loads((ROOT/'RESUMEN.json').read_text());v=json.loads((ROOT/'VERIFICACION_INDEPENDIENTE.json').read_text())
fig,axes=plt.subplots(1,2,figsize=(11,4.5),layout='constrained')
theta=np.linspace(0,2*np.pi,500);a=.5
ax=axes[0];ax.plot(a*np.sin(theta),1+a*np.cos(theta),color='#146e9a',label='Bola de aceleraciones: radio 0,5 g')
zz=np.linspace(0,1.6,300)
for delta,color in [(25,'#b24d39'),(35,'#267e5b')]:
 xx=zz*np.tan(np.deg2rad(delta))
 ax.plot(xx,zz,color=color,label=f'Cono efectivo ±{delta}°');ax.plot(-xx,zz,color=color)
pt=np.array(v['tangent_force_over_mg']);ax.plot([0,pt[0]],[0,pt[2]],'k--',lw=1)
ax.scatter([pt[0]],[pt[2]],color='black',zorder=5);ax.annotate('Tangencia: 30°',pt[[0,2]],xytext=(.13,.47),arrowprops={'arrowstyle':'->'})
ax.scatter([0],[1],color='#146e9a');ax.set(xlim=(-.85,.85),ylim=(0,1.65),xlabel='Fuerza lateral / mg',ylabel='Fuerza vertical / mg',title='Sección del dominio requerido')
ax.set_aspect('equal');ax.legend(fontsize=7,loc='upper left');ax.grid(alpha=.2)
ax=axes[1];delta=np.linspace(0,70,300);ax.plot(delta,np.sin(np.deg2rad(delta)),color='#146e9a',label='Cota necesaria: sin(δ)')
ax.axhline(.5,color='#b24d39',ls='--',label='Escenario 0,5 g');ax.axvline(30,color='gray',ls=':')
ax.set(xlabel='Semiángulo efectivo δ (grados)',ylabel='Radio de aceleración / g',title='Límite por dirección del empuje',ylim=(0,1),xlim=(0,70));ax.legend(fontsize=8);ax.grid(alpha=.2)
fig.suptitle('Modelo ideal: cuerpo horizontal y cuatro empujes de signo positivo',fontsize=12)
fig.savefig(ROOT/'limites_angulo.png',dpi=160);fig.savefig(ROOT/'limites_angulo.svg');plt.close(fig)
lines=['# Sensibilidad a la desviación efectiva del empuje','','## Resultado','','El escenario intermedio de aceleración en cualquier dirección de hasta 0,5 g, con cuerpo horizontal, no requiere necesariamente un cono ideal de 45°. Se encontraron cotas suficientes con 35° y 40° para 2, 5 y 10 kg supuestos, con las mismas capacidades máximas que la referencia previa de 45° hasta tolerancia numérica. Se verificaron independientemente 9.216 vértices conjuntos de fuerza/momento. No se valida ningún módulo instalado.','','El máximo objetivo del proyecto no se reduce a 0,5 g: este estudio es un escalón de caracterización de control. No demuestra vuelo rápido, rechazo dinámico de perturbaciones ni capacidad de maniobra abrupta con actuadores reales.','','## Límite necesario derivado','','Si cada fuerza útil tiene signo axial positivo y pertenece a un cono de semiángulo δ, su suma también pertenece al cono convexo: norma de fuerza lateral ≤ fuerza vertical·tan(δ). No depende de cuánto empuje pueda producir el motor.','','Para una aceleración horizontal pura con altura constante, se requiere δ ≥ atan(a/g): a=0,5 g exige al menos 26,565°. Sin embargo, cubrir la bola completa de aceleraciones tridimensionales exige encerrar una esfera de fuerza de radio 0,5·mg centrada en (0,0,mg). Su tangencia desde el origen está a asin(0,5)=30°. Por tanto, 30° es condición necesaria, sin garantizar los momentos, precargas o capacidades.','','El punto de tangencia es F/(mg)=(0,433013; 0; 0,75), equivalente a aceleración/g=(0,433013; 0; −0,25), de norma 0,5. El verificador comprueba esa distancia y ángulo. No debe confundirse radio de bola de aceleraciones con máximo horizontal aislado.','','Más generalmente, el radio de la bola no puede superar sin(δ)·g bajo estos supuestos. Con δ=15°, 20° o 25°, las cotas necesarias son 0,259 g, 0,342 g y 0,423 g. Aumentar potencia no elimina esa limitación de dirección. Cambiar actitud, permitir signos de fuerza distintos o modificar la geometría de vectorización cambia el problema; estas cotas no se aplican directamente a la variante reversible.','','![Límites del modelo](limites_angulo.png)','','## Cotas suficientes con fuerzas y momentos acoplados','','Cada capacidad es fuerza útil máxima suficiente por ventilador en el modelo; no es empuje de rotor libre, empuje medido ni una selección de motor. Se mantienen los cuatro centros de la arquitectura A y su escalado geométrico s=(m/5)^(1/3), CG en el origen, palancas laterales idealizadas de filas, precarga vertical de (m/5) N por ventilador y reserva simultánea de momento por componente de ±0,5·(m/5)^(5/3) N·m.','','| Masa supuesta | Cono 35° | Cono 40° | Referencia previa 45° |','|---|---:|---:|---:|']
for mass in (2.,5.,10.):
 rr=[it['result'] for it in s['results'] if 'result' in it and it['result']['mass_assumed_kg']==mass]
 by={int(it['effective_cone_half_angle_deg']):it['positive_force_capacity_sufficient_N'] for it in rr}
 lines.append(f'| {mass:g} kg | {by[35]:.3f} N | {by[40]:.3f} N | {by[45]:.3f} N |')
lines += ['','Se usan conos interiores discretizados y un poliedro exterior que contiene la bola de fuerzas; su producto con los ocho vértices de la caja de momentos da 1.536 comprobaciones por caso. La convexidad extiende la cobertura a todo el dominio continuo bajo el modelo, no solo a las direcciones muestreadas. La verificación independiente reconstruye Newton–Euler por componentes, límites de fuerza/cono/precarga y cobertura de la bola mediante las facetas de la envolvente convexa exterior.','','No se calcula aquí el mínimo ángulo suficiente: el límite necesario de 30° y los certificados de 35° dejan una franja pendiente que incluye conservadurismo del poliedro, reservas de momento y otras restricciones. La igualdad de capacidades entre 35°/40°/45° se refiere al peor caso de este dominio concreto y no demuestra equivalencia en agilidad máxima.','','## Consecuencia de diseño','','El mapa instalado debe medir dirección y magnitud de la fuerza neta, incluidos conducto y rotor, además de pares libres. Un ángulo mecánico de álabe no determina el ángulo efectivo del empuje. El resultado instantáneo anterior sobre reacción de paredes no se usa como factor de eficiencia ni como calibración de δ.','','Los tiempos de giro previos, calculados con cono ideal de 45°, no se transfieren automáticamente al cono de 35°: requieren volver a asignar fuerzas con límites temporales para cada trayectoria y con el mapa físico. Falta también comprobar la dependencia de potencia, tasas y cargas estructurales. Ninguna fila demuestra por sí sola que la geometría sea la mejor posible.','','Archivos reproducibles: `../../sensibilidad_angulo_A.py`, `../../verificar_sensibilidad_angulo_A.py`, `../../informar_sensibilidad_angulo_A.py`, `RESUMEN.json`, seis NPZ/JSON de asignaciones y `VERIFICACION_INDEPENDIENTE.json`.']
# Directory is two levels below modelos_integrados? vectorizacion_A/sensibilidad_angulo.
(ROOT/'INFORME.md').write_text('\n'.join(lines)+'\n');print(ROOT/'INFORME.md')
